(SELECT id, text, context, event_date, occurred_start, occurred_end, mentioned_at, fact_type, document_id, chunk_id, tags, metadata, proof_count,        1 - (embedding <=> $1::vector) AS similarity,        NULL::float AS bm25_score,        'semantic' AS source FROM ctxdb_ws_locomo_conv30_20261118_200523.memory_units WHERE bank_id = $2   AND fact_type = 'world'   AND embedding IS NOT NULL   AND (1 - (embedding <=> $1::vector)) >= 0.3          ORDER BY embedding <=> $1::vector LIMIT 1000)
UNION ALL
(SELECT id, text, context, event_date, occurred_start, occurred_end, mentioned_at, fact_type, document_id, chunk_id, tags, metadata, proof_count,        NULL::float AS similarity,        ts_rank_cd(search_vector, to_tsquery('english', $4)) AS bm25_score,        'bm25' AS source FROM ctxdb_ws_locomo_conv30_20261118_200523.memory_units WHERE bank_id = $2   AND fact_type = 'world'   AND search_vector @@ to_tsquery('english', $4)          ORDER BY ts_rank_cd(search_vector, to_tsquery('english', $4)) DESC LIMIT $3)
